/**
 * Favicons and home-screen icons per site.
 *
 * Gym hosts: the gym's app icon (or, failing that, its logo) resized by Cloudinary for each size,
 * or — with neither — a letter icon generated by /gym-icon. Platform host: Fitexaa's static icons
 * from /platform/. A gym host never links a Fitexaa icon.
 *
 * Every URL carries `v` (the branding's updatedAt, or a hash of what the letter icon is drawn from) so
 * a change shows at once even where browsers cached the old icon for a long time.
 */
import type { PublicTenant } from '@fitexaa/api-client';

export type IconLink = { url: string; sizes: string; type: string };
export type SiteIcons = { icon: IconLink[]; apple: IconLink[] };

export const FAVICON_SIZES = [32, 48] as const;
export const APPLE_SIZE = 180;
export const LETTER_ICON_SIZES = [32, 48, 180, 192, 512] as const;

/** Fitexaa's own icons: platform host only. Placeholders in public/platform/, replace freely. */
export const PLATFORM_ICONS: SiteIcons = {
  icon: [
    { url: '/platform/favicon-32.png', sizes: '32x32', type: 'image/png' },
    { url: '/platform/favicon-48.png', sizes: '48x48', type: 'image/png' },
    { url: '/platform/favicon.svg', sizes: 'any', type: 'image/svg+xml' },
  ],
  apple: [{ url: '/platform/apple-touch-icon.png', sizes: '180x180', type: 'image/png' }],
};

/** Small stable hash (FNV-1a, base36) for cache-busting values that aren't timestamps. */
export function shortHash(s: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(36);
}

const CLOUDINARY = /^(https:\/\/res\.cloudinary\.com\/[^/]+\/image\/upload\/)(.+)$/;
/** A path segment of Cloudinary transformations, e.g. "c_fill,w_512,h_512,f_auto,q_auto". */
const TRANSFORM = /^[a-z]{1,3}_[^/]*$/;

function withVersion(url: string, v: string | undefined): string {
  if (!v) return url;
  return `${url}${url.includes('?') ? '&' : '?'}v=${encodeURIComponent(v)}`;
}

/**
 * The image at `size`×`size`. Cloudinary URLs get their transformation replaced: an icon is cropped
 * square (it is square already), a logo is padded on a transparent square so it isn't cut off. Other
 * https URLs (set before uploads were enforced) are used as they are.
 */
export function sizedImage(url: string, size: number, kind: 'icon' | 'logo'): string {
  const m = CLOUDINARY.exec(url);
  if (!m) return url;
  const parts = m[2]!.split('/');
  while (parts.length > 1 && TRANSFORM.test(parts[0]!)) parts.shift();
  const t = kind === 'icon' ? `c_fill,w_${size},h_${size},f_png` : `c_pad,w_${size},h_${size},b_transparent,f_png`;
  return `${m[1]}${t}/${parts.join('/')}`;
}

/** The letter icon's URL: versioned by exactly what it is drawn from (name and colour). */
export function letterIconUrl(tenant: Pick<PublicTenant, 'name' | 'branding'>, size: number): string {
  return `/gym-icon?s=${size}&v=${shortHash(`${tenant.name}|${tenant.branding.primaryColor}`)}`;
}

export function gymIcons(tenant: PublicTenant): SiteIcons {
  const b = tenant.branding;
  const src = b.appIconUrl ?? b.logoUrl;
  const kind = b.appIconUrl ? 'icon' : 'logo';
  const v = b.updatedAt ? String(Date.parse(b.updatedAt) || b.updatedAt) : undefined;
  const at = (size: number) => (src ? withVersion(sizedImage(src, size, kind), v) : letterIconUrl(tenant, size));
  return {
    icon: FAVICON_SIZES.map((s) => ({ url: at(s), sizes: `${s}x${s}`, type: 'image/png' })),
    apple: [{ url: at(APPLE_SIZE), sizes: `${APPLE_SIZE}x${APPLE_SIZE}`, type: 'image/png' }],
  };
}
